-- S1: clasificación final. S2: primera cifra azul (total), sin sumar el desglose.
-- Se conserva Winx por no aparecer en estas imágenes. No modifica PG ni PP.
CREATE TABLE IF NOT EXISTS rck_data_migrations (version VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rck_historical_season_points (
  club_nombre VARCHAR(255) NOT NULL,
  temporada INT NOT NULL,
  puntos INT NOT NULL,
  PRIMARY KEY (club_nombre, temporada)
);
START TRANSACTION;
UPDATE tclubshistoricos c JOIN (SELECT club_nombre, SUM(puntos) total FROM rck_historical_season_points GROUP BY club_nombre) p ON LOWER(TRIM(c.Nombre))=LOWER(p.club_nombre) SET c.Puntuacion=p.total WHERE NOT EXISTS (SELECT 1 FROM rck_data_migrations WHERE version='historical-points-s1-s2-blue-total-20261102');
COMMIT;
